  'https://demo.ravencloak.org/raven/api/v1/healthz',
  'https://demo.raven.ravencloak.org/',
  'https://demo.raven.ravencloak.org/api/v1/healthz',
  'https://observability.ravencloak.org/',
  'https://observability.demo.raven.ravencloak.org/',
];

for (const u of urls) {
  try {
    const r = await fetch(u, { redirect: 'manual', headers: { 'User-Agent': 'raven-deploy-check/1' } });
    const ct = r.headers.get('content-type') || '';
    const loc = r.headers.get('location') || '';
    const cfRay = r.headers.get('cf-ray') || '';
    const server = r.headers.get('server') || '';
    let snippet = '';
    if (ct.includes('text') || ct.includes('json') || ct.includes('html')) {
      const t = await r.text();
      snippet = t.slice(0, 160).replace(/\s+/g, ' ').trim();
    }
    console.log(`${r.status} ${u}`);
    console.log(`   server=${server} ct=${ct} loc=${loc}`);
    if (snippet) console.log(`   body: ${snippet}`);
  } catch (e) {
    console.log(`ERR  ${u} :: ${e.message}`);
  }
}

// 1. Fetch SPA, extract asset URLs, fetch one to verify
const r = await fetch('https://demo.ravencloak.org/raven/');
const html = await r.text();
const scripts = [...html.matchAll(/src="(\/[^"]+\.js)"/g)].map(m => m[1]);
const styles = [...html.matchAll(/href="(\/[^"]+\.css)"/g)].map(m => m[1]);
const icons  = [...html.matchAll(/href="(\/[^"]+\.svg)"/g)].map(m => m[1]);
console.log('script srcs:', scripts);
console.log('style hrefs:', styles);
console.log('icon hrefs:', icons);

// 2. Try the actual asset to see if it 200s
const probes = [
  '/raven/healthz',                          // where the moved /healthz lives now
  '/raven/api/v1/healthz',                   // what monitor might hit
  '/raven/api/v1/config',                    // real public-unauth endpoint
  '/raven/api/v1/auth/sign-up/email',        // SuperTokens via api group
  '/healthz',                                // pre-prefix path
  '/api/v1/healthz',                         // pre-prefix path
];
if (scripts[0]) probes.push(scripts[0]);     // an actual hashed asset
if (styles[0])  probes.push(styles[0]);
if (icons[0])   probes.push(icons[0]);

console.log('\n=== probe results ===');
for (const p of probes) {
  const u = 'https://demo.ravencloak.org' + p;
  try {
    const x = await fetch(u, { redirect: 'manual' });
    let body = '';
    const ct = x.headers.get('content-type') || '';
    if (x.status >= 400 || ct.includes('text/plain') || ct.includes('json')) {
      body = (await x.text()).slice(0, 100).replace(/\s+/g, ' ').trim();
    }
    console.log(`${x.status} ${p}  (${ct})  ${body}`);
