# Self-contained nginx for the path-prefixed Vultr demo build.
# Differences from the repo's frontend/nginx.conf:
#   - Strips the /raven/ prefix for static assets/SPA fallback so files
#     served from the standard /usr/share/nginx/html resolve correctly.
#   - Reverse-proxies /raven/{api,auth,webhooks}/* to the go-api container
#     so the SPA can use same-origin calls without CORS.
#
# This file is COPYed into the image at /etc/nginx/conf.d/default.conf
# only for the path-prefixed variant build (deploy/vultr/Dockerfile.frontend
# overlay or via docker cp during ad-hoc builds).
server {
    listen 8080;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

